mapper.insert:
INSERT INTO PRODUCT_PIC (PICTURE_ID, PRODUCT_ID, PICTURE_URL, PICTURE_ORDER, PICTURE_REGDATE) SELECT PRODUCT_PIC_SEQ.NEXTVAL, t.productId, t.pictureUrl, t.pictureOrder, SYSTIMESTAMP FROM (
SELECT #{pic.productId} AS productId, #{pic.pictureUrl} AS pictureUrl, #{pic.pictureOrder} AS pictureOrder FROM DUAL
) t

mapper.select:
SELECT * FROM PRODUCT_PIC WHERE PRODUCT_ID = #{productId}
ORDER BY
